def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    for y,row in enumerate(grid):
        xs=[x for x,v in enumerate(row) if v==5]
        for a,b in zip(xs,xs[1:]):
            for x in range(a+1,b): out[y][x]=3
    for x in range(w):
        ys=[y for y in range(h) if grid[y][x]==5]
        for a,b in zip(ys,ys[1:]):
            for y in range(a+1,b): out[y][x]=3
    return out
